P=Path(__file__).resolve().parent
base='''@font-face{font-family:Inter;src:url(assets/inter-latin-400-normal.woff2);font-weight:400}@font-face{font-family:Inter;src:url(assets/inter-latin-700-normal.woff2);font-weight:700}@font-face{font-family:Inter;src:url(assets/inter-latin-800-normal.woff2);font-weight:800}*{box-sizing:border-box}body{margin:0;font-family:Inter;background:white;color:#151a22}h1,h2,h3,p{margin:0}footer{position:absolute;bottom:42px;left:60px;right:60px;display:flex;justify-content:space-between;border-top:2px solid currentColor;padding-top:18px;font-size:21px}'''
def save(name,body,css='',w=1080,h=1350):
 s=f'<!doctype html><html><head><meta charset="utf-8"><style>{base}body{{width:{w}px;height:{h}px;position:relative;overflow:hidden}}{css}</style></head><body>{body}</body></html>';(P/f'{name}.html').write_text(s)
def footer(label):return f'<footer><b>WITHHAMMAD</b><span>{label}</span><span>withhammad.com</span></footer>'
for i,(title,sub,sections,flow) in enumerate(NLP):
 body=f'<div class="page">{i+1:02} / 20</div><header><div class="series">THE NLP FIELD NOTEBOOK</div><h1>{E(title)}</h1><p>{E(sub)}</p></header>'
 body+='<main>'+''.join(f'<section><div class="n">{i}.{j+1}</div><h2>{E(t)}</h2><p>{E(v)}</p></section>' for j,(t,v) in enumerate(sections))+'</main>'
 body+=f'<div class="flow">{E(flow)}</div>'+footer('Developer study notes')
 css='''body{background:#fffef9;color:#183e83;border:14px solid #e8e5dc}body:before{content:"";position:absolute;left:50%;top:350px;bottom:280px;width:1px;background:#cad2df}.page{position:absolute;right:55px;top:40px;font-size:22px}.series{font-size:19px;letter-spacing:3px;font-weight:700;margin-bottom:24px}header{padding:72px 54px 25px;border-bottom:2px solid #183e83;margin:0 32px}h1{font-family:Georgia,serif;font-size:65px;line-height:1.05;letter-spacing:-2px;color:#182034}header p{font-size:27px;line-height:1.35;margin-top:20px}main{display:grid;grid-template-columns:1fr 1fr;gap:45px 52px;padding:44px 60px}section{min-height:245px}.n{font-size:18px;font-weight:700;margin-bottom:10px}h2{font-size:29px;line-height:1.2;margin-bottom:17px}section p{font-size:25px;line-height:1.55}.flow{position:absolute;left:60px;right:60px;bottom:150px;border:2px solid #183e83;padding:24px;text-align:center;font-family:Georgia,serif;font-size:31px;line-height:1.3}'''
 if i==0:css+='body:before{display:none}.n{display:none}header{padding-top:175px;text-align:center}h1{font-size:180px;letter-spacing:-7px}header p{font-size:44px;font-family:Georgia,serif}main{padding-top:70px}section p{font-size:27px}'
 save(f'nlp-{i+1:02}',body,css)
