groups=[('FOUNDATIONS','#0675d0',[('Transformer','Attention and feature transformations build context-aware representations.'),('Language model','A causal LLM predicts a next-token distribution from prior context.'),('Tokenization','A tokenizer converts text into units and numerical identifiers.'),('Embeddings','Learned vectors represent tokens, text or other inputs.')]),('KNOWLEDGE & CONTEXT','#248a36',[('Context window','The token capacity available for the model’s input and output.'),('Prompt design','Specify the task, context, constraints and expected result.'),('Vector search','Retrieve nearby representations, often alongside keyword filters.'),('RAG','Retrieve evidence and use it in generation; verify the answer.')]),('TRAINING & EVALUATION','#b9520c',[('Fine-tuning','Adapt a pretrained model with examples and a training objective.'),('RLHF','Use human preference signals in a reinforcement-learning process.'),('Quantization','Use lower-precision numbers; check memory savings and quality.'),('Evaluations','Test task performance, failures, latency and cost on held-out cases.')]),('AGENTS & PRODUCTION','#7848bf',[('Agent loop','Select actions, observe results and continue within a defined budget.'),('Tool calling','The model proposes a call; application code validates and runs it.'),('MCP','A protocol for compatible applications to exchange context and tools.'),('Guardrails','Enforce checks and permissions around inputs, actions and outputs.')])]
body='<header><p>A PRACTICAL REFERENCE</p><h1>16 AI CONCEPTS<br><span>WORTH UNDERSTANDING</span></h1></header><main class="concepts">'
